from .tokens import FormulaError, tokenize

COMPARE = ("=", "<>", "<", ">", "<=", ">=")


class _Parser:
    def __init__(self, tokens):
        self.t = tokens
        self.i = 0

    def peek(self):
        return self.t[self.i] if self.i < len(self.t) else ("end", None)

    def next(self):
        tok = self.peek()
        self.i += 1
        return tok

    def accept(self, value):
        tok = self.peek()
        if tok[0] == "op" and tok[1] == value:
            self.i += 1
            return True
        return False

    def expect(self, value):
        if not self.accept(value):
            raise FormulaError(f"expected {value!r}")

    def expr(self):
        left = self.sum()
        tok = self.peek()
        if tok[0] == "op" and tok[1] in COMPARE:
            self.next()
            return ("bin", tok[1], left, self.sum())
        return left

    def sum(self):
        left = self.term()
        while self.peek()[0] == "op" and self.peek()[1] in ("+", "-"):
            op = self.next()[1]
            left = ("bin", op, left, self.term())
        return left

    def term(self):
        left = self.unary()
        while self.peek()[0] == "op" and self.peek()[1] in ("*", "/"):
            op = self.next()[1]
            left = ("bin", op, left, self.unary())
        return left

    def unary(self):
        if self.accept("-"):
            return ("neg", self.unary())
        return self.power()

    def power(self):
        base = self.atom()
        if self.accept("^"):
            return ("bin", "^", base, self.unary())
        return base

    def atom(self):
        kind, val = self.next()
        if kind in ("num", "str"):
            return (kind, val)
        if kind == "ref":
