        cond = evaluate(args[0], read)
        if isinstance(cond, Err):
            return cond
        if cond is None:
            cond = 0.0
        if isinstance(cond, str):
            return VALUE
        return evaluate(args[1] if cond != 0 else args[2], read)
    if name not in AGGREGATES:
        return NAME
    nums = []
    for a in args:
        if a[0] == "range":
            for ref in cells_in(a[1], a[2]):
                v = read(ref)
                if isinstance(v, Err):
                    return v
                if isinstance(v, float):
                    nums.append(v)
        else:
            v = evaluate(a, read)
            if isinstance(v, Err):
                return v
            if v is None:
                continue
            if isinstance(v, str):
                return VALUE
            nums.append(v)
