    if op in COMPARE:
        return _compare(op, left, right)
    left, right = number(left), number(right)
    for v in (left, right):
        if isinstance(v, Err):
            return v
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        return DIV0 if right == 0 else left / right
    return _power(left, right)


