    for v in (left, right):
        if isinstance(v, Err):
            return v
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        return DIV0 if right == 0 else left / right
    return _power(left, right)


def _power(a, b):
    try:
        r = a ** b
    except ZeroDivisionError:
        return DIV0
    except OverflowError:
        return NUM
    return NUM if isinstance(r, complex) else r


def _compare(op, left, right):
    for v in (left, right):
        if isinstance(v, Err):
            return v
    if left is None:
        left = "" if isinstance(right, str) else 0.0
    if right is None:
        right = "" if isinstance(left, str) else 0.0
    if isinstance(left, str) != isinstance(right, str):
        if op == "=":
            return 0.0
        if op == "<>":
            return 1.0
        return VALUE
    if isinstance(left, str):
        left, right = left.lower(), right.lower()
    result = {"=": left == right, "<>": left != right, "<": left < right, ">": left > right, "<=": left <= right, ">=": left >= right}[op]
    return 1.0 if result else 0.0


def _call(name, args, read):
    if name == "IF":
        if len(args) != 3:
            return VALUE
        cond = evaluate(args[0], read)
        if isinstance(cond, Err):
            return cond
        if cond is None:
            cond = 0.0
        if isinstance(cond, str):
            return VALUE
        return evaluate(args[1] if cond != 0 else args[2], read)
