        return float(len(nums))
    if name == "SUM":
        return math.fsum(nums)
    if not nums:
        return DIV0 if name == "AVG" else 0.0
    if name == "AVG":
        return math.fsum(nums) / len(nums)
    return min(nums) if name == "MIN" else max(nums)

