                if k2 != "ref":
                    raise FormulaError("a range needs two cells")
                return ("range", val, v2)
            return ("ref", val)
        if kind == "func":
            self.expect("(")
            args = []
            if not self.accept(")"):
                args.append(self.expr())
                while self.accept(","):
                    args.append(self.expr())
                self.expect(")")
            return ("call", val, args)
        if kind == "op" and val == "(":
            inner = self.expr()
            self.expect(")")
            return inner
        raise FormulaError(f"unexpected {val!r}" if kind != "end" else "unexpected end")


