    """The nodes ordered so that every cell comes after the cells it reads (only edges inside `nodes` count)."""
    order = []
    done = set()

    def visit(c):
        if c in done:
            return
        done.add(c)
        for d in sorted(deps.get(c, ())):
            if d in nodes:
                visit(d)
        order.append(c)

    for c in sorted(nodes):
        visit(c)
    return order

