AGGREGATES = ("SUM", "MIN", "MAX", "AVG", "COUNT")


def number(v):
    if isinstance(v, Err):
        return v
    if v is None:
        return 0.0
    if isinstance(v, str):
        return VALUE
    return v


def evaluate(node, read):
    """Value of a syntax tree; `read(cell)` gives the value of another cell."""
    kind = node[0]
    if kind in ("num", "str"):
        return node[1]
    if kind == "ref":
        return read(node[1])
    if kind == "range":
        return VALUE
    if kind == "neg":
        v = number(evaluate(node[1], read))
        return v if isinstance(v, Err) else -v
    if kind == "bin":
        return _binary(node[1], evaluate(node[2], read), evaluate(node[3], read))
    return _call(node[1], node[2], read)


def _binary(op, left, right):
    if op in COMPARE:
        return _compare(op, left, right)
    left, right = number(left), number(right)
    for v in (left, right):
        if isinstance(v, Err):
            return v
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        return DIV0 if right == 0 else left / right
    return _power(left, right)


