                seen.add(u)
                todo.append(u)
    return seen


def cyclic(nodes, users):
    """The nodes that lie on a cycle of the `users` graph (a node that is its own user included)."""
    out = set()
    for n in nodes:
        seen = set()
        todo = [u for u in users.get(n, ()) if u in nodes]
        while todo:
            c = todo.pop()
            if c == n:
                out.add(n)
                break
            if c in seen:
                continue
            seen.add(c)
            todo.extend(u for u in users.get(c, ()) if u in nodes)
    return out


