    if kind in ("num", "str"):
        return node[1]
    if kind == "ref":
        return read(node[1])
    if kind == "range":
        return VALUE
    if kind == "neg":
        v = number(evaluate(node[1], read))
        return v if isinstance(v, Err) else -v
    if kind == "bin":
        return _binary(node[1], evaluate(node[2], read), evaluate(node[3], read))
    return _call(node[1], node[2], read)


def _binary(op, left, right):
    if op in COMPARE:
        return _compare(op, left, right)
    left, right = number(left), number(right)
    for v in (left, right):
        if isinstance(v, Err):
            return v
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        return DIV0 if right == 0 else left / right
    return _power(left, right)


def _power(a, b):
    try:
        r = a ** b
    except ZeroDivisionError:
        return DIV0
    except OverflowError:
        return NUM
    return NUM if isinstance(r, complex) else r


def _compare(op, left, right):
    for v in (left, right):
        if isinstance(v, Err):
            return v
    if left is None:
        left = "" if isinstance(right, str) else 0.0
    if right is None:
        right = "" if isinstance(left, str) else 0.0
    if isinstance(left, str) != isinstance(right, str):
        if op == "=":
            return 0.0
        if op == "<>":
            return 1.0
        return VALUE
    if isinstance(left, str):
        left, right = left.lower(), right.lower()
    result = {"=": left == right, "<>": left != right, "<": left < right, ">": left > right, "<=": left <= right, ">=": left >= right}[op]
    return 1.0 if result else 0.0


def _call(name, args, read):
    if name == "IF":
        if len(args) != 3:
            return VALUE
        cond = evaluate(args[0], read)
        if isinstance(cond, Err):
            return cond
        if cond is None:
            cond = 0.0
        if isinstance(cond, str):
            return VALUE
        return evaluate(args[1] if cond != 0 else args[2], read)
    if name not in AGGREGATES:
        return NAME
    nums = []
    for a in args:
        if a[0] == "range":
            for ref in cells_in(a[1], a[2]):
                v = read(ref)
                if isinstance(v, Err):
                    return v
                if isinstance(v, float):
                    nums.append(v)
        else:
            v = evaluate(a, read)
            if isinstance(v, Err):
                return v
            if v is None:
                continue
            if isinstance(v, str):
                return VALUE
            nums.append(v)
    if name == "COUNT":
        return float(len(nums))
    if name == "SUM":
        return math.fsum(nums)
    if not nums:
        return DIV0 if name == "AVG" else 0.0
    if name == "AVG":
        return math.fsum(nums) / len(nums)
    return min(nums) if name == "MIN" else max(nums)

